import {roles,suppliers,catalog,seed,amount,money,labels,modules} from './data.js';
const $=s=>document.querySelector(s), main=$('#main');
let orders=seed(), role='maker', route='home', group='工作台', current=null, draft=null, dirty=false, recent=[], page=1, filter={state:'',supplier:'',q:'',date:'',exec:''};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',box:'M3 7l9-4 9 4v12l-9 4-9-4V7zm0 0 9 5 9-5M12 12v11',cart:'M2 3h3l3 13h11l3-10H6M9 20h1m7 0h1',file:'M6 3h8l4 4v14H6V3zm8 0v5h4M9 12h6m-6 4h6',chart:'M4 21V10h4v11m4 0V3h4v18m4 0V7h3v14',money:'m5 3 7 8 7-8M12 11v11M5 11h14M5 16h14',settings:'M12 3v4m0 10v4M3 12h4m10 0h4M6 6l3 3m6 6 3 3M6 18l3-3m6-6 3-3M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const badge=o=>`<span class="badge ${o.state}">${labels[o.state]||'未保存'}</span>`;
const progress=o=>o.state==='approved'?`<span class="progress"><span class="track"><i style="width:${o.progress}%"></i></span>${o.progress}%</span>`:'<span class="muted">—</span>';
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',4000)}
function leave(fn){if(!dirty)return fn();$('#confirm').showModal();$('#stay').onclick=()=>$('#confirm').close();$('#leave').onclick=()=>{$('#confirm').close();dirty=false;fn()}}
function nav(r,g='采购'){leave(()=>{route=r;group=g;draft=null;dirty=false;history.pushState({r,g},'',`#${r}`);render();window.scrollTo(0,0)})}
function open(id){leave(()=>{current=id;route='detail';group='采购';draft=structuredClone(orders.find(o=>o.id===id));recent=[id,...recent.filter(x=>x!==id)].slice(0,5);history.pushState({r:'detail',g:group,id},'',`#order/${id}`);render();window.scrollTo(0,0)})}
function newOrder(){leave(()=>{current=null;draft={id:'新采购订单',supplier:'',date:'2026-10-28',due:'2026-11-03',state:'new',owner:role,progress:0,lines:[],terms:'',events:[]};route='detail';group='采购';dirty=false;history.pushState({r:'new'},'','#new');render()})}
function sidebar(){const list=['工作台','基础资料','采购','销售','库存','收付款','报表'];$('#sidebar').innerHTML=`<div class="brand">五金 <span>ERP</span></div><nav class="nav" aria-label="业务导航">${list.map((n,i)=>`<button data-nav="${n}" class="${group===n?'active':''}" aria-expanded="${group===n}">${icon(['home','box','cart','chart','box','money','file'][i])}${n}</button>${group===n&&modules[n]?modules[n].map(x=>`<button class="sub ${x==='采购订单'&&['list','detail'].includes(route)?'active':''}" data-sub="${x}">${x}</button>`).join(''):''}`).join('')}</nav><button class="settings" data-nav="系统设置">${icon('settings')}系统设置</button>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{nav(b.dataset.nav==='工作台'?'home':b.dataset.nav==='采购'?'list':'module',b.dataset.nav);$('#sidebar').classList.remove('open')});document.querySelectorAll('[data-sub]').forEach(b=>b.onclick=()=>{if(b.dataset.sub==='采购订单')nav('list');else nav('preview:'+b.dataset.sub,group);$('#sidebar').classList.remove('open')})}
function canApprove(o){return o.owner!==role&&((role==='manager'&&o.state==='pending')||(role==='owner'&&o.state==='review'))}
function table(rows){return `<div class="table-wrap"><table><thead><tr><th>单据编号</th><th>供应商</th><th>订单日期</th><th class="num">含税总额（元）</th><th>审批状态</th><th>入库进度</th><th>操作</th></tr></thead><tbody>${rows.map(o=>`<tr><td><button class="link" data-open="${o.id}">${o.id}</button></td><td>${esc(o.supplier)}</td><td>${o.date}</td><td class="num">${money(amount(o))}</td><td>${badge(o)}</td><td>${progress(o)}</td><td><button class="link" data-open="${o.id}">查看</button></td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">暂无符合条件的采购订单<br><button class="link" id="empty-reset">重置筛选</button></div>':''}</div>`}
function home(){const pending=orders.filter(canApprove),awaiting=orders.filter(o=>o.state==='approved'&&o.progress<100);main.innerHTML=`<div class="page-head"><div><h1>工作台</h1><p>把每天的业务，安排得井井有条。</p></div><span class="muted">2026年10月28日 · 演示日期</span></div><section class="panel"><div class="panel-head"><h2>常用操作</h2><span class="muted">采购业务</span></div><div class="quick"><button id="quick-new" ${role!=='maker'?'disabled':''}><span class="icon-box">${icon('cart')}</span><strong>新增采购订单</strong><small>录入商品与采购数量</small></button><button id="quick-list"><span class="icon-box">${icon('file')}</span><strong>采购订单查询</strong><small>查看审批与入库进度</small></button><button id="quick-stock"><span class="icon-box">${icon('box')}</span><strong>库存业务</strong><small>浏览模块导航</small></button></div></section><div class="home-grid"><section class="panel"><div class="panel-head"><h2>我的待办</h2><span class="muted">当前模拟身份</span></div><div class="panel-body"><div class="task"><span class="count">${pending.length}</span><div><strong>待我审批</strong><div class="muted">按角色筛选，排除本人制单</div></div><button id="pending" class="link">查看 →</button></div><div class="task"><span class="count">${awaiting.length}</span><div><strong>待入库采购订单</strong><div class="muted">已批准，尚未全部入库</div></div><button id="awaiting" class="link">查看 →</button></div></div></section><section class="panel"><div class="panel-head"><h2>采购怎么走</h2></div><div class="panel-body"><div class="step"><b>1</b><div><strong>采购经办录单</strong><span class="muted">保存后待审批，尚未生效</span></div></div><div class="step"><b>2</b><div><strong>独立审批人复核</strong><span class="muted">超过 10,000 元，转负责人复核</span></div></div><div class="step" style="margin:0"><b>3</b><div><strong>按订单办理入库</strong><span class="muted">审批通过与入库进度分别记录</span></div></div></div></section></div><section class="panel"><div class="panel-head"><h2>最近访问</h2><button class="link" id="all">全部采购订单 →</button></div>${recent.length?table(recent.map(id=>orders.find(o=>o.id===id))):'<div class="empty">还没有访问记录。打开一张采购订单后，会在这里保留入口。</div>'}</section>`;$('#quick-new').onclick=newOrder;$('#quick-list').onclick=()=>nav('list');$('#all').onclick=()=>nav('list');$('#quick-stock').onclick=()=>nav('module','库存');$('#pending').onclick=()=>{filter={state:'mine',supplier:'',q:'',date:'',exec:''};page=1;nav('list')};$('#awaiting').onclick=()=>{filter={state:'approved',supplier:'',q:'',date:'',exec:'awaiting'};page=1;nav('list')}}
function filtered(){return orders.filter(o=>(!filter.state||(filter.state==='mine'?canApprove(o):o.state===filter.state))&&(!filter.supplier||o.supplier===filter.supplier)&&o.id.toLowerCase().includes(filter.q.toLowerCase())&&(!filter.date||o.date===filter.date)&&(!filter.exec||(filter.exec==='awaiting'?o.state==='approved'&&o.progress<100:o.state==='approved'&&o.progress===100)))}
function list(){const rows=filtered();page=Math.min(page,Math.max(1,Math.ceil(rows.length/5)));const part=rows.slice((page-1)*5,page*5);main.innerHTML=`<div class="page-head"><div><h1>采购订单</h1><p>管理订单与入库进度</p></div><button id="new" class="primary" ${role!=='maker'?'disabled title="请切换为采购经办"':''}>＋ 新增采购订单</button></div><section class="panel"><div class="tabs">${[['','全部'],['pending','待审批'],['review','待负责人复核'],['approved','已批准'],['cancelled','已撤销']].map(([v,t])=>`<button data-tab="${v}" class="${filter.state===v?'selected':''}">${t}</button>`).join('')}</div><form id="filters" class="filters"><div class="field"><label for="supplier">供应商</label><select id="supplier"><option value="">全部供应商</option>${suppliers.map(x=>`<option ${filter.supplier===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="query">单据编号</label><input id="query" placeholder="输入单据编号" value="${esc(filter.q)}"></div><div class="field"><label for="date">订单日期</label><input type="date" id="date" value="${filter.date}"></div><div class="field"><label for="exec">执行状态</label><select id="exec"><option value="">全部</option value="awaiting" ${filter.exec==='awaiting'?'selected':''}>待入库 / 部分入库</option><option value="done" ${filter.exec==='done'?'selected':''}>全部入库</option></select></div><button class="primary">查询</button><button type="button" id="reset">重置</button></form>${filter.state==='mine'?'<div class="notice">仅显示当前身份可审批的模拟订单</div>':''}${table(part)}<div class="table-foot"><span>本页合计：<strong>${money(part.reduce((n,o)=>n+amount(o),0))}</strong> 元　共 ${rows.length} 条</span><div class="actions"><button id="prev" ${page===1?'disabled':''}>上一页</button><span>${page} / ${Math.max(1,Math.ceil(rows.length/5))}</span><button id="next" ${page*5>=rows.length?'disabled':''}>下一页</button><span>5 条/页</span></div></div></section>`;$('#new').onclick=newOrder;$('#filters').onsubmit=e=>{e.preventDefault();filter={...filter,supplier:$('#supplier').value,q:$('#query').value.trim(),date:$('#date').value,exec:$('#exec').value};page=1;render()};const reset=()=>{filter={state:'',supplier:'',q:'',date:'',exec:''};page=1;render()};$('#reset').onclick=reset;if($('#empty-reset'))$('#empty-reset').onclick=reset;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{filter.state=b.dataset.tab;page=1;render()});$('#prev').onclick=()=>{page--;render()};$('#next').onclick=()=>{page++;render()}}
function detail(){const o=draft;if(!o){nav('list');return}const edit=role==='maker'&&o.owner===role&&['new','pending'].includes(o.state);main.innerHTML=`<div class="page-head"><div><button class="link" id="back">← 返回采购订单</button><h1 style="margin-top:12px">${o.id}</h1><div class="recent-title">${badge(o)}<span class="muted">${o.state==='approved'?'已生效 · 审批与入库分别记录':'模拟单据 · 不影响真实库存与账务'}</span></div></div><div class="actions">${edit?'<button id="save" class="primary">保存</button>':''}${canApprove(o)?`<button id="approve" class="primary">${role==='owner'?'负责人批准':amount(o)>10000?'转负责人复核':'批准'}</button>`:''}${role==='owner'&&o.state==='review'&&o.owner!==role?'<button id="return">退回重填</button>':''}${role==='manager'&&o.state==='approved'&&o.owner!==role?'<button id="cancel" class="danger">撤销</button>':''}</div></div><div class="notice">当前体验：${roles[role]}。${edit?'可编辑本人未生效订单；保存后由独立审批人处理。':'当前页面按模拟身份及单据状态展示可用操作。'} 此示例税费为 0，不代表实际税务设置。</div><section class="panel"><div class="panel-head"><h2>基本信息</h2><span class="muted">公司：示例五金贸易公司 · 人民币 CNY</span></div><div class="panel-body form-grid"><div class="field"><label for="d-supplier">供应商 *</label><select id="d-supplier" ${!edit?'disabled':''}><option value="">请选择供应商</option>${suppliers.map(x=>`<option ${o.supplier===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="d-date">订单日期 *</label><input id="d-date" type="date" value="${o.date}" ${!edit?'disabled':''}></div><div class="field"><label for="d-due">要求到货日期 *</label><input id="d-due" type="date" value="${o.due}" ${!edit?'disabled':''}></div><div class="field"><label>默认收货仓库</label><input value="示例主仓" disabled></div><div class="field"><label>制单人</label><input value="${roles[o.owner]}" disabled></div><div class="field"><label>入库进度</label><div style="padding-top:12px">${progress(o)}</div></div><span class="error" id="error" role="alert"></span></div></section><section class="panel"><div class="panel-head"><h2>商品明细 <span class="muted">${o.lines.length} 项</span></h2>${edit?'<div class="actions"><select id="catalog" aria-label="选择商品">'+catalog.map((x,i)=>`<option value="${i}">${x.name}</option>`).join('')+'</select><button id="add" style="white-space:nowrap">＋ 添加商品</button></div>':''}</div><div class="table-wrap"><table><thead><tr><th>商品编码</th><th>商品名称 / 说明</th><th>数量</th><th>单位</th><th class="num">单价</th><th class="num">金额</th>${edit?'<th></th>':''}</tr></thead><tbody>${o.lines.map((l,i)=>`<tr><td>${l.code}</td><td>${l.name}<div class="muted">${l.desc}</div></td><td>${edit?`<input class="line-input" type="number" min="1" step="1" aria-label="${l.name}数量" data-qty="${i}" value="${l.qty}">`:l.qty}</td><td>${l.unit}</td><td class="num">${money(l.price)}</td><td class="num">${money(l.price*l.qty)}</td>${edit?`<td><button class="link danger" data-remove="${i}">移除</button></td>`:''}</tr>`).join('')}</tbody></table>${!o.lines.length?'<div class="empty">请添加商品，填写采购数量。</div>':''}</div><div class="summary"><div><span class="muted">净额</span><strong>¥ ${money(amount(o))}</strong></div><div><span class="muted">税费合计（模拟）</span><strong>¥ 0.00</strong></div><div class="total"><span class="muted">含税总额</span><strong>¥ ${money(amount(o))}</strong></div></div></section><div class="detail-grid"><section class="panel"><div class="panel-head"><h2>条款与关联单据</h2></div><div class="panel-body"><label class="muted" for="terms">条款说明</label><textarea id="terms" rows="3" ${!edit?'disabled':''}>${esc(o.terms)}</textarea><p class="mini">${o.progress>0?'模拟关联：DEMO-PR-0001（仅展示，不生成真实入库）':'暂无关联入库单'}</p></div></section><section class="panel"><div class="panel-head"><h2>操作记录</h2></div><div class="panel-body">${o.events.length?o.events.map(x=>`<div class="event">${esc(x.text)}<div class="muted">${esc(x.who)} · ${esc(x.time)}</div></div>`).join(''):'<span class="muted">保存后记录操作</span>'}</div></section></div>`;$('#back').onclick=()=>nav('list');if(edit){const sync=()=>{o.supplier=$('#d-supplier').value;o.date=$('#d-date').value;o.due=$('#d-due').value;o.terms=$('#terms').value;dirty=true};['#d-supplier','#d-date','#d-due','#terms'].forEach(s=>$(s).oninput=sync);$('#add').onclick=()=>{sync();o.lines.push({...catalog[+$('#catalog').value],qty:1});render()};document.querySelectorAll('[data-qty]').forEach(el=>el.onchange=()=>{sync();o.lines[+el.dataset.qty].qty=Math.max(1,Math.floor(Number(el.value)||1));render()});document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{sync();o.lines.splice(+el.dataset.remove,1);render()});$('#save').onclick=()=>{sync();if(!o.supplier||!o.date||!o.due||!o.lines.length){$('#error').textContent=!o.supplier?'请选择供应商':!o.date||!o.due?'请填写订单日期和要求到货日期':'请添加商品';$('#d-supplier').setAttribute('aria-invalid',String(!o.supplier));if(!o.supplier)$('#d-supplier').focus();return}if(!current){o.id=`DEMO-PO-2026-${String(orders.length+1).padStart(4,'0')}`;o.state='pending';orders.unshift(structuredClone(o));current=o.id}record('保存采购订单');history.replaceState({r:'detail',g:'采购',id:current},'',`#order/${current}`);dirty=false;render();toast('已保存，尚未生效；当前为待审批')}}if($('#approve'))$('#approve').onclick=()=>{if(!canApprove(o))return toast('当前身份不能审批此单');o.state=role==='manager'&&amount(o)>10000?'review':'approved';record(labels[o.state]);render();toast('模拟状态已更新：'+labels[o.state])};if($('#return'))$('#return').onclick=()=>{o.state='pending';record('退回重填');render();toast('已退回重填，仍未生效')};if($('#cancel'))$('#cancel').onclick=()=>{if(o.progress>0)return toast('已有模拟入库关联，须先处理后续单据');if(window.confirm('确认撤销该模拟订单？')){o.state='cancelled';record('撤销采购订单');render();toast('模拟订单已撤销')}}}
function record(text){draft.events.unshift({text,who:roles[role],time:new Date().toLocaleTimeString('zh-CN',{hour12:false})});const i=orders.findIndex(o=>o.id===current);if(i>=0)orders[i]=structuredClone(draft)}
function modulePage(){const title=route.startsWith('preview:')?route.slice(8):group;main.innerHTML=`<div class="page-head"><div><h1>${esc(title)}</h1><p>模块导航预览</p></div></div><div class="notice">本轮可操作原型覆盖工作台与采购订单。此处展示信息架构，尚未接入业务页面。</div><section class="panel"><div class="panel-body module-links">${(modules[group]||[]).map(x=>`<button data-module="${x}">${x}<span style="float:right;color:#8d9ab0">→</span></button>`).join('')}</div></section><button id="return-demo" class="primary">体验采购订单</button>`;document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>nav('preview:'+b.dataset.module,group));$('#return-demo').onclick=()=>nav('list')}
function render(){sidebar();$('#crumb').textContent=group+(route==='detail'?' / 采购订单 / 单据详情':route==='list'?' / 采购订单':'');if(route==='home')home();else if(route==='list')list();else if(route==='detail')detail();else modulePage();document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>open(b.dataset.open))}
$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#role').onchange=e=>{const next=e.target.value;e.target.value=role;leave(()=>{role=next;$('#role').value=role;dirty=false;if(current&&route==='detail')draft=structuredClone(orders.find(o=>o.id===current));else if(route==='detail'){route='home';group='工作台';draft=null}render()})};window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});window.addEventListener('popstate',e=>{leave(()=>{route=e.state?.r||'home';group=e.state?.g||'工作台';current=e.state?.id||null;draft=current?structuredClone(orders.find(o=>o.id===current)):null;if(route==='new')route='home';render()})});render();

document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#sidebar').classList.remove('open')});document.addEventListener('click',e=>{if(!e.target.closest('#sidebar,#menu'))$('#sidebar').classList.remove('open')});
